#!/usr/bin/env python3
"""Sum git show --numstat -M over a list of commits, by category.
usage: classify.py LANDING_COMMIT commit...   (run in repo root)
Prints per-category totals and per-file table to stdout (tsv)."""
import subprocess, sys, os, re, collections, json

def git(*a):
    return subprocess.run(['git', *a], capture_output=True, text=True, errors='replace').stdout

COORD = {
    'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
    'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
    'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md'}
TEST_DIRS = ('ProjectFortress/tests/', 'ProjectFortress/compiler_tests/',
             'ProjectFortress/library_tests/', 'ProjectFortress/not_passing_yet/',
             'ProjectFortress/static_tests/', 'ProjectFortress/parser_tests/',
             'ProjectFortress/unit_tests/', 'ProjectFortress/compiler_tests_expected/')
CAP = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.awk', '.pl', '.jq', '.rb', '.sed', '.mjs'}

def cat(p):
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'):
        return 'CODE-library'
    if p.startswith('ProjectFortress/src/'):
        if p.endswith('.java'): return 'CODE-java'
        if p.endswith('.scala'): return 'CODE-scala'
        return 'CODE-src-other'
    if p.startswith('ProjectFortress/astgen/') or os.path.basename(p) in ('build.xml', 'ant', 'build.properties'):
        return 'CODE-build'
    if p.startswith('ProjectFortress/demos/'):
        return 'CODE-demos'
    if p == 'Specification/fortress.pdf': return 'SPEC-pdf'
    if p.startswith('Specification/') and p.endswith('.tex'): return 'SPEC-tex'
    if p.startswith('Specification'): return 'SPEC-other'
    if p.startswith(TEST_DIRS): return 'TESTS'
    if p in COORD: return 'COORD'
    if p.startswith('explorations/'):
        ext = os.path.splitext(p)[1]
        if ext == '.md': return 'REC-REPORTS'
        if ext in CAP: return 'REC-CAPTURES'
        if ext in PROBE: return 'REC-PROBES'
        if ext in SCRIPT: return 'REC-SCRIPTS'
        return 'REC-OTHER'
    return 'ELSEWHERE'

def commit_rows(c):
    """yield (status, oldpath, newpath, add, del) for commit c."""
    ns = git('show', '--numstat', '-M', '-z', '--format=', c)
    st = git('show', '--name-status', '-M', '-z', '--format=', c)
    # parse name-status
    toks = st.split('\0'); i = 0; status = {}
    while i < len(toks):
        t = toks[i]
        if not t: i += 1; continue
        if t[0] in 'RC':
            status[toks[i+2]] = (t[0], toks[i+1]); i += 3
        else:
            status[toks[i+1]] = (t[0], None); i += 2
    toks = ns.split('\0'); i = 0; out = []
    while i < len(toks):
        t = toks[i]
        if not t.strip(): i += 1; continue
        parts = t.split('\t')
        a, d = parts[0], parts[1]
        if len(parts) >= 3 and parts[2] == '':
            old, new = toks[i+1], toks[i+2]; i += 3
        else:
            old = new = parts[2]; i += 1
        s = status.get(new, ('?', None))[0]
        out.append((s, old, new, None if a == '-' else int(a), None if d == '-' else int(d)))
    return out

def main():
    landing = sys.argv[1]; commits = sys.argv[2:]
    files = collections.OrderedDict()  # path -> dict
    for c in commits:
        for s, old, new, a, d in commit_rows(c):
            f = files.setdefault(new, {'cat': cat(new), 'add': 0, 'del': 0, 'binary': False,
                                       'statuses': [], 'commits': [], 'old': None})
            if a is None: f['binary'] = True
            else: f['add'] += a; f['del'] += d
            f['statuses'].append(s); f['commits'].append(c[:9])
            if s == 'R': f['old'] = old
    # bytes and lines at landing
    for p, f in files.items():
        sz = git('cat-file', '-s', f'{landing}:{p}').strip()
        f['exists'] = bool(sz)
        f['bytes'] = int(sz) if sz else 0
        if sz and not f['binary']:
            f['lines_now'] = git('show', f'{landing}:{p}').count('\n')
        else:
            f['lines_now'] = 0
    json.dump(files, sys.stdout, indent=0)

main()

